import{C as d,o as l,c as i,a2 as e,E as o}from"./chunks/framework.CFuv5BrO.js";const c=JSON.parse('{"title":"交付路线与实施计划","description":"Hearth 的交付总纲：七个能力阶段、35 个纵向增量、140 个工作包，以及每阶段的出口证据。","frontmatter":{"title":"交付路线与实施计划","description":"Hearth 的交付总纲：七个能力阶段、35 个纵向增量、140 个工作包，以及每阶段的出口证据。","outline":[2,3]},"headers":[],"relativePath":"delivery/index.md","filePath":"delivery/index.md","lastUpdated":1793784691000}'),n={name:"delivery/index.md"},m=Object.assign(n,{setup(s){const a=[{no:"S0",meta:"4 个增量",title:"定义与原型",text:"产品楔子、真实任务、可点击原型、协议契约与评测基线。",link:"/delivery/stage-0"},{no:"S1",meta:"6 个增量",title:"持久内核与 MVP",text:"走路骨架、第一个 Codex 切片、MVP-1、副作用安全与恢复。",link:"/delivery/stage-1"},{no:"S2",meta:"6 个增量",title:"Personal Operator",text:"连接器、文档与数据、网页研究，以及需要审批的写入。",link:"/delivery/stage-2"},{no:"S3",meta:"4 个增量",title:"Computer Operator",text:"桌面 agentd、GUI 观察、人工接管和分级桌面动作。",link:"/delivery/stage-3"},{no:"S4",meta:"5 个增量",title:"主动个人 Agent",text:"Trigger、主动收件箱、手机 PWA 与注意力预算。",link:"/delivery/stage-4"},{no:"S5",meta:"4 个增量",title:"记忆与进化",text:"Memory Core、遗忘与导出、技能候选、评估与回滚。",link:"/delivery/stage-5"},{no:"S6",meta:"6 个增量",title:"多设备与长期运行",text:"事件同步、离线队列、设备撤销、备份迁移与长期运维。",link:"/delivery/stage-6"}];return(h,t)=>{const r=d("DocCardGrid");return l(),i("div",null,[t[0]||(t[0]=e('<p class="eyebrow">DELIVERY</p><h1 id="交付路线与实施计划" tabindex="-1">交付路线与实施计划 <a class="header-anchor" href="#交付路线与实施计划" aria-label="Permalink to &quot;交付路线与实施计划&quot;">​</a></h1><p class="lead">这里只有一套总纲：Stage 0–6 定义能力门槛，35 个 D 增量定义具体施工顺序，每个增量再拆成四个工作包。路线不承诺日期，只承诺每阶段可见的产品结果、验证证据和恢复路径。</p><h2 id="推进原则" tabindex="-1">推进原则 <a class="header-anchor" href="#推进原则" aria-label="Permalink to &quot;推进原则&quot;">​</a></h2><ul><li><strong>Stage 是能力门槛，不是工期。</strong> 可以停留、试用和回退，但不能跳过恢复、界面、验证或安全边界。</li><li><strong>每个增量都是纵向切片。</strong> 用户结果、界面、持久状态、真实执行、验证与恢复必须同时出现。</li><li><strong>MVP 尽早出现。</strong> MVP-1 是 Stage 1 的早期出口，不是等项目结束才形成的演示。</li><li><strong>先窄后宽。</strong> 先让一个任务族真正可依赖，再扩展连接器、桌面、主动性和多设备。</li><li><strong>安全先于副作用。</strong> 发送、写入、分享、删除和桌面操作必须先有授权、幂等和回执。</li><li><strong>证据先于宣布。</strong> 阶段是否完成，以真实任务、故障恢复和评测结果判断，不以“代码写完”判断。</li></ul><h2 id="七个阶段" tabindex="-1">七个阶段 <a class="header-anchor" href="#七个阶段" aria-label="Permalink to &quot;七个阶段&quot;">​</a></h2>',6)),o(r,{items:a,columns:2}),t[1]||(t[1]=e('<h2 id="阶段总览" tabindex="-1">阶段总览 <a class="header-anchor" href="#阶段总览" aria-label="Permalink to &quot;阶段总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>用户得到什么</th><th>进入下一阶段前必须证明</th></tr></thead><tbody><tr><td>Stage 0</td><td>可点击的端到端原型</td><td>产品楔子、12 个真实任务、稳定契约、评测与审批基线</td></tr><tr><td>Stage 1</td><td>本地每天可用的个人任务工作台</td><td>持久状态、真实 Codex 执行、审批、产物、失败恢复与 MVP-1</td></tr><tr><td>Stage 2</td><td>能处理日常内容工作的 Personal Operator</td><td>连接器闭环、引用来源、文档/数据验证、审批写入与回执</td></tr><tr><td>Stage 3</td><td>能操作桌面的 Computer Operator</td><td>GUI 观察、人工接管、隔离、桌面验证与高风险审批</td></tr><tr><td>Stage 4</td><td>低打扰的主动个人 Agent</td><td>Trigger、注意力预算、手机审批、暂停与设备撤销</td></tr><tr><td>Stage 5</td><td>会积累上下文并安全改进方法的 Agent</td><td>记忆可纠正/遗忘/导出，技能有评估、晋升和回滚</td></tr><tr><td>Stage 6</td><td>多设备、可迁移、长期运行的 Personal Agent OS</td><td>同步一致、离线恢复、设备撤销、迁移与长期运维证据</td></tr></tbody></table><p>具体目标、范围与退出条件在对应阶段页展开；阶段之间按能力依赖推进，不按日历切换。</p><h2 id="_35-个增量-140-个工作包" tabindex="-1">35 个增量，140 个工作包 <a class="header-anchor" href="#_35-个增量-140-个工作包" aria-label="Permalink to &quot;35 个增量，140 个工作包&quot;">​</a></h2><p>每个 D 增量都按同一模板交付，避免“后端做完了但用户看不到”的伪进度：</p><table tabindex="0"><thead><tr><th>交付项</th><th>必须回答</th></tr></thead><tbody><tr><td>用户可见结果</td><td>用户能在浏览器里多做哪一件具体的事？</td></tr><tr><td>实现与工程落点</td><td>哪些模块、接口、事件和测试需要完成？</td></tr><tr><td>验收演练</td><td>用什么可重复的步骤证明它真的完成？</td></tr><tr><td>失败与恢复</td><td>失败时用户看到什么，如何取消、重试、接管或撤销？</td></tr></tbody></table><p>每个增量包含四个实施工作包；工作包可以分工，但不能用其中任何一个的完成代替整个增量的验收。</p><h2 id="mvp-在哪里" tabindex="-1">MVP 在哪里 <a class="header-anchor" href="#mvp-在哪里" aria-label="Permalink to &quot;MVP 在哪里&quot;">​</a></h2><p>MVP-1 位于 Stage 1 的 D1.3，是一个真实可用的本地个人任务工作台。它必须包含 Web 任务卡、持久任务状态、真实 Codex 执行、产物、审批演练和失败恢复，但不包含邮件、日历、GUI、主动循环和多设备。</p><h2 id="六条执行规则" tabindex="-1">六条执行规则 <a class="header-anchor" href="#六条执行规则" aria-label="Permalink to &quot;六条执行规则&quot;">​</a></h2><ol><li><strong>纵向切片优先。</strong> 不交付只有 CLI、日志、数据库或接口的“半成品阶段”。</li><li><strong>前端同步生长。</strong> Stage 0 有原型，Stage 1 有真实 Web 任务卡，之后每个增量都必须有用户路径。</li><li><strong>持久性先于自主性。</strong> 任务不能丢、副作用不能重复、失败必须可见。</li><li><strong>安全先于真实副作用。</strong> 高风险动作必须经过预览、授权、幂等和回执。</li><li><strong>评估先于扩展。</strong> 新执行器、连接器、模型和技能都要有代表性任务、基线和失败样本。</li><li><strong>范围可以裁，地基不能裁。</strong> 先减少覆盖和主动性，不减少界面、状态、恢复、审计和撤权。</li></ol><h2 id="工程约束" tabindex="-1">工程约束 <a class="header-anchor" href="#工程约束" aria-label="Permalink to &quot;工程约束&quot;">​</a></h2><p>每个阶段还必须满足以下工程底线：契约与集成测试、故障注入、安全测试、性能与长稳测试、可观测字段、备份导出和可回滚发布。详细仓库布局、测试体系、风险与决策已移入附录：</p><ul><li><a href="/hearth-os/reference/engineering.html">工程实施与仓库结构</a></li><li><a href="/hearth-os/reference/risks.html">风险与 Kill Criteria</a></li><li><a href="/hearth-os/reference/decisions.html">ADR 与关键决策</a></li></ul><h2 id="现在从这里开始" tabindex="-1">现在从这里开始 <a class="header-anchor" href="#现在从这里开始" aria-label="Permalink to &quot;现在从这里开始&quot;">​</a></h2><p>先读<a href="/hearth-os/design/">项目设计与取舍</a>理解为什么这样设计，再从 <a href="/hearth-os/delivery/stage-0.html">Stage 0</a> 开始。已经明确当前阶段时，可直接从侧栏进入对应阶段和 D 增量。</p>',16))])}}});export{c as __pageData,m as default};
